    List<com.example.starter.wb.domain.CargoCompartment> all = jdbc.sql("""
                    SELECT c.id, c.aircraft_id, c.code, c.arm_mm, c.max_weight_kg, c.label,
                           a.uld_type
                    FROM cargo_compartment c
                    LEFT JOIN compartment_uld_allowed a ON a.compartment_id = c.id
                    WHERE c.aircraft_id = :aid
                    ORDER BY c.id, a.uld_type
                    """)
            .param("aid", aircraftId)
            .query((rs, n) -> new CargoCompartment(
                    rs.getLong("id"), rs.getLong("aircraft_id"), rs.getString("code"),
                    rs.getInt("arm_mm"), rs.getInt("max_weight_kg"), rs.getString("label"),
                    rs.getString("uld_type") == null ? List.of() : List.of(rs.getString("uld_type"))))
            .list();
    // 同舱位多行（多个允许类型）合并为一条主数据
    Map<Long, CargoCompartment> merged = new LinkedHashMap<>();
    for (CargoCompartment c : all) {
        CargoCompartment cur = merged.get(c.id());
        if (cur == null) {
            merged.put(c.id(), new CargoCompartment(c.id(), c.aircraftId(), c.code(),
                    c.armMm(), c.maxWeightKg(), c.label(), List.copyOf(c.allowedUldTypes())));
        } else {
            List<String> types = new java.util.ArrayList<>(cur.allowedUldTypes());
            c.allowedUldTypes().stream().filter(t -> !types.contains(t)).forEach(types::add);
            merged.put(c.id(), new CargoCompartment(cur.id(), cur.aircraftId(), cur.code(),
                    cur.armMm(), cur.maxWeightKg(), cur.label(), List.copyOf(types)));
        }
    }
    return List.copyOf(merged.values());
}

