public final class WeightBalanceCalculator {

    private static final int CG_SCALE = 4;
    private static final int MOMENT_SCALE = 2;
    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
    /** 英寸到毫米的精确换算因子；舱位力臂为整数毫米，计算全程以毫米进行避免换算舍入。 */
    private static final BigDecimal MM_PER_INCH = new BigDecimal("25.4");

    private WeightBalanceCalculator() {
    }

    public static WeightBalanceResult calculate(Aircraft ac, List<CalcLoadItem> items, BigDecimal fuelKg) {
        BigDecimal payload = BigDecimal.ZERO.setScale(MOMENT_SCALE);
        BigDecimal payloadMoment = BigDecimal.ZERO.setScale(MOMENT_SCALE);
        int pax = 0;
        for (CalcLoadItem item : items) {
            payload = payload.add(item.weightKg());
            payloadMoment = payloadMoment.add(item.moment());
            if (item.isPassenger()) {
                pax += item.pieces();
            }
        }
        return finish(ac, pax, payload, payloadMoment, fuelKg);
    }

    /**
     * 装配图驱动的载重平衡：货运业载（CARGO/MAIL）由装配图总重与精确力矩（kg·mm）替代，
     * 其余业载按站位力臂（英寸）精确折算毫米后求和，重心判定沿用既有包线与重量规则。
     *
     * @param nonCargoItems   非货运业载（旅客/行李），力臂单位英寸
     * @param cargoWeightKg   装配图总货重（含皮重），整数 kg
     * @param cargoMomentKgmm 装配图总力矩，kg·mm（总重乘整数毫米力臂精确求和）
     */
    public static WeightBalanceResult calculateWithAssembly(Aircraft ac, List<CalcLoadItem> nonCargoItems,
                                                            int cargoWeightKg, long cargoMomentKgmm,
                                                            BigDecimal fuelKg) {
        BigDecimal payload = BigDecimal.valueOf(cargoWeightKg).setScale(MOMENT_SCALE);
        BigDecimal payloadMomentIn = BigDecimal.ZERO.setScale(MOMENT_SCALE);
        int pax = 0;
        for (CalcLoadItem item : nonCargoItems) {
            payload = payload.add(item.weightKg());
            payloadMomentIn = payloadMomentIn.add(item.moment());
            if (item.isPassenger()) {
                pax += item.pieces();
            }
        }
        // 英寸力矩精确折算毫米后与装配图力矩求和；结果力矩字段仍按英寸返回（换算精确可逆）。
        BigDecimal payloadMomentMm = payloadMomentIn.multiply(MM_PER_INCH)
                .add(BigDecimal.valueOf(cargoMomentKgmm));
