// --------------------------------------------------------- 集装器装配图

@Override
@Transactional
public AssemblyDiagramResponse submitAssembly(long flightId, SubmitAssemblyRequest request) {
    String fp = fingerprint(request.requestId(), request);
    Optional<IdempotentRow> existing = idempotencyStore.find(request.requestId());
    if (existing.isPresent()) {
        return replay(existing.get(), fp, request.requestId(), AssemblyDiagramResponse.class);
    }
    AssemblyDiagramResponse response;
    try {
        response = doSubmitAssembly(flightId, request, fp);
    } catch (DuplicateKeyException dke) {
        // 并发决胜：同键已提交则回放，其余唯一冲突（两航班抢同器/并发改图）转业务拒绝。
        Optional<IdempotentRow> raced = idempotencyStore.find(request.requestId());
        if (raced.isPresent() && raced.get().fingerprint().equals(fp)) {
            return replay(raced.get(), fp, request.requestId(), AssemblyDiagramResponse.class);
        }
        throw new UnprocessableException("集装器或装配图版本并发冲突，本版拒绝（同一集装器同时刻仅一笔占用成功）");
    }
    // 业务、版本、占用与幂等结果同事务落库：失败回滚不占键，可同键重试。
    repo.insertIdempotent(new IdempotentRow(request.requestId(), fp, 200,
            safeJson(response), LocalDateTime.now(clock)));
    return response;
}

private AssemblyDiagramResponse doSubmitAssembly(long flightId, SubmitAssemblyRequest request, String fp) {
    // FOR UPDATE 锁定有效舱单行：同航班并发改图在此串行，最多一方版本推进成功。
    ActiveCtx ctx = requireActive(flightId);
    ManifestRow row = ctx.row();
    // 锁内复查同键请求：先提交者已落幂等结果时直接回放。
    Optional<IdempotentRow> raced = idempotencyStore.find(request.requestId());
    if (raced.isPresent()) {
        return replay(raced.get(), fp, request.requestId(), AssemblyDiagramResponse.class);
    }
    String status = row.status();
    if (ManifestStatus.CLOSED.name().equals(status)) {
        throw new ConflictException("舱单已放行关闭，装配图历史版本只读");
    }
    if (ManifestStatus.PRELIMINARY.name().equals(status)) {
        throw new ConflictException("请先完成值机确定货运业载后再提交装配图，当前状态 " + status);
    }

    Aircraft ac = ctx.aircraft();
    List<CargoCompartment> compartments = repo.findCompartments(ac.id());
    Map<String, CargoCompartment> compartmentByCode = new HashMap<>();
    compartments.forEach(c -> compartmentByCode.put(c.code(), c));

    // 逐项校验：皮重非负/净重为正；编号图内唯一；舱位存在且同舱最多一器；类型在允许列表。
    Set<String> seenNumbers = new HashSet<>();
    Set<String> seenCompartments = new HashSet<>();
    Map<String, Integer> weightByCompartment = new HashMap<>();
    List<AssemblyItemRow> itemRows = new ArrayList<>();
    int seq = 0;
    int totalWeight = 0;
    long totalMoment = 0L;
    for (AssemblyItemRequest item : request.items()) {
        if (item.tareKg() < 0 || item.netKg() <= 0) {
            throw new BadRequestException("皮重须非负、净重须为正：" + item.uldNumber());
        }
        if (!seenNumbers.add(item.uldNumber())) {
            throw new UnprocessableException("集装器编号 " + item.uldNumber() + " 在同一装配图内重复");
        }
        if (!seenCompartments.add(item.compartmentCode())) {
            throw new UnprocessableException("舱位 " + item.compartmentCode() + " 已安排集装器，同舱位最多一器");
        }
        CargoCompartment compartment = compartmentByCode.get(item.compartmentCode());
        if (compartment == null) {
            throw new BadRequestException("飞机 " + ac.tailNo() + " 不存在舱位 " + item.compartmentCode());
        }
        if (!compartment.allowedUldTypes().contains(item.uldType())) {
            throw new UnprocessableException("舱位 " + compartment.code() + " 不允许集装器类型 "
                    + item.uldType() + "，允许 " + compartment.allowedUldTypes());
        }
        int itemTotal = item.tareKg() + item.netKg();
        int compWeight = weightByCompartment.merge(compartment.code(), itemTotal, Integer::sum);
        if (compWeight > compartment.maxWeightKg()) {
            throw new UnprocessableException("舱位 " + compartment.code() + " 总重 " + compWeight
                    + "kg 超过限额 " + compartment.maxWeightKg() + "kg（恰达限额合法）");
        }
        totalWeight += itemTotal;
        totalMoment += (long) itemTotal * compartment.armMm();
        itemRows.add(new AssemblyItemRow(null, 0, item.uldNumber(), item.uldType(),
                compartment.code(), item.tareKg(), item.netKg(), itemTotal, seq++));
    }

    // 装配图总货重（含皮重）须与该舱单版本货运业载（CARGO+MAIL）精确相等。
    BigDecimal cargoPayload = BigDecimal.ZERO.setScale(2);
    List<LoadDetailRow> details = repo.findDetails(row.id());
    for (LoadDetailRow d : details) {
        if (LoadCategory.CARGO.name().equals(d.category()) || LoadCategory.MAIL.name().equals(d.category())) {
            cargoPayload = cargoPayload.add(d.totalWeightKg());
        }
    }
    if (cargoPayload.compareTo(BigDecimal.valueOf(totalWeight)) != 0) {
        throw new UnprocessableException("装配图总货重 " + totalWeight + "kg（含皮重）与舱单货运业载 "
                + cargoPayload + "kg 不一致，整版拒绝");
    }

    // 货运力矩按总重乘整数毫米力臂精确求和后，交由既有重心/重量规则校验。
    List<CalcLoadItem> nonCargoItems = toCalcItems(details, ac, true);
    WeightBalanceResult wb = WeightBalanceCalculator.calculateWithAssembly(
            ac, nonCargoItems, totalWeight, totalMoment, row.fuelKg());
    ensureWithinLimits(wb);

    // 期望版本：无图须为 0，有图须等于当前版本；成功后新版本 = expectedVersion + 1。
    Optional<AssemblyDiagramRow> current = repo.findCurrentDiagram(flightId);
    int expectedCurrentVersion = current.map(AssemblyDiagramRow::version).orElse(0);
    if (request.expectedVersion() != expectedCurrentVersion) {
        throw new ConflictException("装配图版本冲突：期望 " + request.expectedVersion()
                + "，当前为 " + expectedCurrentVersion);
    }

    // 跨未关闭航班占用检查；本航班既有占用允许整版替换。
    List<UldOccupancyRow> ownOccupancy = repo.findActiveOccupancyByFlight(flightId);
    Map<String, UldOccupancyRow> ownByNumber = new HashMap<>();
    ownOccupancy.forEach(o -> ownByNumber.put(o.uldNumber(), o));
    for (AssemblyItemRow item : itemRows) {
        Optional<UldOccupancyRow> held = repo.findActiveOccupancyByUld(item.uldNumber());
        if (held.isPresent() && held.get().flightId() != flightId) {
            throw new UnprocessableException("集装器 " + item.uldNumber() + " 已被未关闭航班 "
                    + held.get().flightId() + " 占用，整版拒绝");
        }
    }

    LocalDateTime now = LocalDateTime.now(clock);
    int newVersion = expectedCurrentVersion + 1;
    // 原子写新图：旧图置 SUPERSEDED（历史图只读、可追溯）。
    if (current.isPresent()) {
        repo.supersedeCurrentDiagrams(flightId);
    }
    long diagramId = repo.insertDiagram(new AssemblyDiagramRow(
            null, flightId, row.id(), newVersion, request.requestId(), fp,
            totalWeight, totalMoment, "CURRENT", request.operator(), now));
    repo.insertDiagramItems(diagramId, itemRows);

    // 占用整版对账：保留（随图转移）/新增/释放均在同一事务。
    Set<String> newNumbers = new HashSet<>();
    itemRows.forEach(i -> newNumbers.add(i.uldNumber()));
    for (AssemblyItemRow item : itemRows) {
        UldOccupancyRow own = ownByNumber.get(item.uldNumber());
        if (own != null) {
            repo.transferOccupancy(own.id(), diagramId);
        } else {
            repo.insertOccupancy(new UldOccupancyRow(null, item.uldNumber(), flightId,
                    diagramId, 1, now, null));
        }
    }
    for (UldOccupancyRow old : ownOccupancy) {
        if (!newNumbers.contains(old.uldNumber())) {
            repo.releaseOccupancy(old.id(), now);
        }
    }

    // 更新货运力矩与重心；装配提交使旧双岗复核失效，不得沿用旧复核。
    String newStatus = ManifestStatus.REVIEWED.name().equals(status)
            ? ManifestStatus.LOADED.name() : status;
    repo.deleteReviews(row.id());
    repo.updateComputed(copyRow(row, wb, newStatus, row.lmcPaxDelta(), row.lmcWeightDelta(), now));

    return toAssemblyResponse(repo.findManifestById(row.id()).orElseThrow(),
            repo.findDiagramByIdHelper(diagramId).orElseThrow(),
            repo.findDiagramItems(diagramId));
}

