public AssemblyDiagramResponse getCurrentAssembly(long flightId) {
    requireFlight(flightId);
    AssemblyDiagramRow diagram = repo.findCurrentDiagram(flightId)
            .orElseThrow(() -> new NotFoundException("航班 " + flightId + " 尚未提交集装器装配图"));
    return toAssemblyResponse(diagram, repo.findDiagramItems(diagram.id()));
}

@Override
@Transactional(readOnly = true)
public List<AssemblyDiagramResponse> listAssemblyVersions(long flightId) {
    requireFlight(flightId);
    return repo.findDiagramsByFlight(flightId).stream()
            .map(d -> toAssemblyResponse(d, repo.findDiagramItems(d.id())))
            .toList();
}

private AssemblyDiagramResponse toAssemblyResponse(AssemblyDiagramRow diagram,
                                                   List<AssemblyItemRow> items) {
    return new AssemblyDiagramResponse(
            diagram.id(), diagram.flightId(), diagram.manifestId(), diagram.version(),
            diagram.totalWeightKg(), diagram.totalMomentKgmm(), diagram.status(),
            List.copyOf(items), diagram.createdBy(), diagram.createdAt());
}

