@Transactional
public AssemblyDiagramResponse submitAssembly(long flightId, SubmitAssemblyRequest request) {
    // 指纹覆盖 requestId、航班与全部业务字段（含版本、集合与精确时刻），结构化无歧义。
    String fp = fingerprint(request.requestId(), new AssemblySubmitPayload(flightId, request));
    Optional<IdempotentRow> existing = idempotencyStore.find(request.requestId());
    if (existing.isPresent()) {
        return replay(existing.get(), fp, request.requestId(), AssemblyDiagramResponse.class);
    }
    AssemblyDiagramResponse response;
    try {
        response = doSubmitAssembly(flightId, request, fp);
        // 业务、版本、占用与幂等结果同事务落库：失败回滚不占键，可同键重试。
        repo.insertIdempotent(new IdempotentRow(request.requestId(), fp, 200,
                safeJson(response), LocalDateTime.now(clock)));
    } catch (DuplicateKeyException dke) {
        // 并发唯一约束决胜：同键同参回放，同键异参 409，其余（两航班抢同器等）业务拒绝。
        Optional<IdempotentRow> raced = idempotencyStore.find(request.requestId());
        if (raced.isPresent()) {
            return replay(raced.get(), fp, request.requestId(), AssemblyDiagramResponse.class);
        }
        throw new UnprocessableException("集装器或装配图版本并发冲突，本版拒绝（同一集装器同时刻仅一笔占用成功）");
    }
    return response;
}

