package com.example.starter.wb.service;

import com.example.starter.wb.AbstractIntegrationTest;
import com.example.starter.wb.dto.AssemblyDiagramResponse;
import com.example.starter.wb.dto.AssemblyItemRequest;
import com.example.starter.wb.dto.CheckinRequest;
import com.example.starter.wb.dto.CloseRequest;
import com.example.starter.wb.dto.CreateManifestRequest;
import com.example.starter.wb.dto.LmcRequest;
import com.example.starter.wb.dto.LoadItem;
import com.example.starter.wb.dto.ManifestResponse;
import com.example.starter.wb.dto.ReviewRequest;
import com.example.starter.wb.dto.StageRequest;
import com.example.starter.wb.dto.SubmitAssemblyRequest;
import com.example.starter.wb.exception.BadRequestException;
import com.example.starter.wb.exception.ConflictException;
import com.example.starter.wb.exception.NotFoundException;
import com.example.starter.wb.exception.UnprocessableException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * H2 集成测试：集装器装配图主流程与失败分支——舱位限额（恰达合法）、图内唯一、
 * 总货重等于货运业载、版本联动、复核失效、关闭释放占用、跨航班占用与历史图只读。
 */
class AssemblyDiagramServiceTest extends AbstractIntegrationTest {

    private static final long FLIGHT_ID = 1L;
    private static final long FLIGHT_ID_2 = 2L;

    @Autowired
    private WeightBalanceService service;

    private static String rid() {
        return UUID.randomUUID().toString();
    }

    /** 90 人 @80kg@PAX_F = 7200kg；6 件 @1000kg@CARGO_F = 6000kg 货运业载。 */
    private static List<LoadItem> baseItems() {
        return List.of(
                new LoadItem("PASSENGER", "PAX_F", 90, new BigDecimal("80")),
                new LoadItem("CARGO", "CARGO_F", 6, new BigDecimal("1000")));
    }

    private ManifestResponse toLoaded(long flightId, List<LoadItem> items, BigDecimal fuel) {
        service.createManifest(new CreateManifestRequest(rid(), flightId, fuel, "lc001", items));
        service.checkin(flightId, new CheckinRequest(rid(), items, fuel, "agent01"));
        return service.confirmLoad(flightId, new StageRequest(rid(), "loader01"));
    }

    private static AssemblyItemRequest uld(String number, String type, String compartment,
                                           int tareKg, int netKg) {
        return new AssemblyItemRequest(number, type, compartment, tareKg, netKg);
    }

    private static SubmitAssemblyRequest assembly(String requestId, long expectedVersion,
                                                  List<AssemblyItemRequest> items) {
        return new SubmitAssemblyRequest(requestId, expectedVersion, items, "lc001",
                LocalDateTime.of(2026, 9, 27, 9, 30, 0));
    }

    /** 标准合法装配图：FWD 恰达 4000kg 限额（含皮重），AFT 2000kg，合计 6000kg = 货运业载。 */
    private static List<AssemblyItemRequest> standardDiagram() {
        return List.of(
                uld("AKE00001", "AKE", "FWD", 100, 3900),
                uld("PMC00002", "PMC", "AFT", 80, 1920));
    }

    private void reviewBoth(long flightId) {
        service.review(flightId, new ReviewRequest(rid(), "LOAD_CONTROLLER", "lc001"));
        service.review(flightId, new ReviewRequest(rid(), "FLIGHT_DISPATCHER", "fd002"));
    }

    // ----------------------------------------------------- 主流程

    @Test
    void submitAssemblyWritesDiagramUpdatesCargoMomentAndOccupancy() {
        ManifestResponse loaded = toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        BigDecimal cgBefore = loaded.cgZfwPct();

        AssemblyDiagramResponse diagram = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 0, standardDiagram()));

        assertThat(diagram.version()).isEqualTo(1);
        assertThat(diagram.manifestId()).isEqualTo(loaded.manifestId());
        assertThat(diagram.status()).isEqualTo("CURRENT");
        assertThat(diagram.totalWeightKg()).isEqualTo(6000);
        // 力矩 = 4000×12700 + 2000×20320 = 91,440,000 kg·mm（总重乘整数毫米力臂精确求和）
        assertThat(diagram.totalMomentKgmm()).isEqualTo(91_440_000L);
        assertThat(diagram.items()).hasSize(2);
        assertThat(diagram.items().get(0).totalKg()).isEqualTo(4000);

        // 货运力矩更新：舱单重心按装配图重算且与站位口径不同，业载总量不变
        ManifestResponse after = service.getActive(FLIGHT_ID);
        assertThat(after.cgZfwPct()).isNotEqualByComparingTo(cgBefore);
        assertThat(after.payloadKg()).isEqualByComparingTo("13200.00");
        assertThat(after.withinLimits()).isTrue();

        // 实物占用落库：两件均在占用中
        Integer occupied = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE active_marker = 1", Integer.class);
        assertThat(occupied).isEqualTo(2);

        // 查询：当前图与版本链
        AssemblyDiagramResponse current = service.getCurrentAssembly(FLIGHT_ID);
        assertThat(current.diagramId()).isEqualTo(diagram.diagramId());
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).hasSize(1);
    }

    @Test
    void resubmitReplacesDiagramAtomicallyAndInvalidatesReviews() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        reviewBoth(FLIGHT_ID);
        assertThat(service.getActive(FLIGHT_ID).status()).isEqualTo("REVIEWED");

        // 复核冻结后提交装配图：原子写新图、旧双岗复核失效、状态回到 LOADED
        AssemblyDiagramResponse v1 = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 0, standardDiagram()));
        ManifestResponse after = service.getActive(FLIGHT_ID);
        assertThat(after.status()).isEqualTo("LOADED");
        assertThat(after.confirmedRoles()).isEmpty();
        Integer reviews = jdbc.queryForObject(
                "SELECT COUNT(*) FROM review_confirmation WHERE manifest_id = ?",
                Integer.class, after.manifestId());
        assertThat(reviews).isZero();

        // 换版：旧图 SUPERSEDED 只读可追溯，同编号占用随图转移
        AssemblyDiagramResponse v2 = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 1, List.of(
                        uld("AKE00001", "AKE", "FWD", 100, 3900),
                        uld("AKE00003", "AKE", "AFT", 50, 1950))));
        assertThat(v2.version()).isEqualTo(2);

        List<AssemblyDiagramResponse> versions = service.listAssemblyVersions(FLIGHT_ID);
        assertThat(versions).hasSize(2);
        assertThat(versions.get(0).status()).isEqualTo("SUPERSEDED");
        assertThat(versions.get(0).items()).hasSize(2);
        assertThat(versions.get(1).status()).isEqualTo("CURRENT");

        // 旧编号 AKE00001 转移至新图，PMC00002 释放，AKE00003 新增；占用总数仍 2
        Integer occupied = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE active_marker = 1", Integer.class);
        assertThat(occupied).isEqualTo(2);
        Long pmcReleased = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE uld_number='PMC00002' AND active_marker IS NULL AND released_at IS NOT NULL",
                Long.class);
        assertThat(pmcReleased).isEqualTo(1);
        Long transferred = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE uld_number='AKE00001' AND active_marker=1 AND diagram_id=?",
                Long.class, v2.diagramId());
        assertThat(transferred).isEqualTo(1);
        assertThat(v1.diagramId()).isNotEqualTo(v2.diagramId());
    }

    @Test
    void closeReleasesOccupancyAtomicallyAfterMatchingCheck() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, standardDiagram()));
        reviewBoth(FLIGHT_ID);

        ManifestResponse closed = service.close(FLIGHT_ID, new CloseRequest(rid(), "captain"));
        assertThat(closed.status()).isEqualTo("CLOSED");

        Integer occupied = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE active_marker = 1", Integer.class);
        assertThat(occupied).isZero();
        Integer released = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE released_at IS NOT NULL", Integer.class);
        assertThat(released).isEqualTo(2);

        // 关闭后装配图只读：再提交被拒绝
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 1, standardDiagram())))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("关闭");
    }

    // ----------------------------------------------------- 失败分支

    @Test
    void compartmentOverLimitAndTypeNotAllowedAndDuplicatesAreRejected() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));

        // FWD 4001kg 超限额 1kg → 422（恰达 4000 在主流程用例验证合法）
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 101, 3900),
                uld("PMC00002", "PMC", "AFT", 80, 1919)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("限额");

        // BULK 不允许 PMC → 422
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 100, 3900),
                uld("PMC00002", "PMC", "BULK", 80, 1920)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("不允许");

        // 同编号重复 → 422
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 100, 3900),
                uld("AKE00001", "AKE", "AFT", 80, 1920)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("重复");

        // 同舱位两器 → 422
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 100, 2000),
                uld("PMC00002", "PMC", "FWD", 80, 1920)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("最多一器");

        // 失败均不落图
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).isEmpty();
    }

    @Test
    void invalidParamsReturn400AndUnknownObjects404() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));

        // 皮重为负 → 400
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", -1, 4000),
                uld("PMC00002", "PMC", "AFT", 80, 1921)))))
                .isInstanceOf(BadRequestException.class);
        // 净重为零 → 400
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 100, 0),
                uld("PMC00002", "PMC", "AFT", 80, 5920)))))
                .isInstanceOf(BadRequestException.class);
        // 未知舱位 → 400
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "NOPE", 100, 3900),
                uld("PMC00002", "PMC", "AFT", 80, 1920)))))
                .isInstanceOf(BadRequestException.class)
                .hasMessageContaining("舱位");

        // 无舱单航班提交 → 404；查询无图航班 → 404
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID_2,
                assembly(rid(), 0, standardDiagram())))
                .isInstanceOf(NotFoundException.class);
        assertThatThrownBy(() -> service.getCurrentAssembly(FLIGHT_ID_2))
                .isInstanceOf(NotFoundException.class);
        assertThatThrownBy(() -> service.submitAssembly(999L,
                assembly(rid(), 0, standardDiagram())))
                .isInstanceOf(NotFoundException.class);
    }

    @Test
    void cargoTotalMustEqualManifestCargoPayload() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        // 总货重 5900 ≠ 货运业载 6000 → 422 整版拒绝
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, List.of(
                uld("AKE00001", "AKE", "FWD", 100, 3900),
                uld("PMC00002", "PMC", "AFT", 80, 1820)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("货运业载");
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).isEmpty();
    }

    @Test
    void expectedVersionIsEnforcedFromOne() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        // 无图时期望版本须为 0
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 1, standardDiagram())))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("版本冲突");

        AssemblyDiagramResponse v1 = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 0, standardDiagram()));
        assertThat(v1.version()).isEqualTo(1);

        // 过期期望版本 → 409
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 0, standardDiagram())))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("版本冲突");
        // 正确期望版本 → 版本 +1
        AssemblyDiagramResponse v2 = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 1, standardDiagram()));
        assertThat(v2.version()).isEqualTo(2);
    }

    @Test
    void submitBeforeCheckinIsRejected() {
        service.createManifest(new CreateManifestRequest(rid(), FLIGHT_ID,
                new BigDecimal("5000"), "lc001", baseItems()));
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 0, standardDiagram())))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("值机");
    }

    @Test
    void crossFlightUldOccupancyRejectedUntilReleased() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, standardDiagram()));

        // 航班 2 货运业载 1000kg；同编号 AKE00001 被航班 1 占用 → 422
        List<LoadItem> items2 = List.of(
                new LoadItem("PASSENGER", "PAX_F", 10, new BigDecimal("80")),
                new LoadItem("CARGO", "CARGO_F", 1, new BigDecimal("1000")));
        toLoaded(FLIGHT_ID_2, items2, new BigDecimal("3000"));
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID_2,
                assembly(rid(), 0, List.of(uld("AKE00001", "AKE", "FWD", 100, 900)))))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("占用");

        // 航班 1 关闭放行后占用释放，航班 2 可装同编号
        reviewBoth(FLIGHT_ID);
        service.close(FLIGHT_ID, new CloseRequest(rid(), "captain"));
        AssemblyDiagramResponse d2 = service.submitAssembly(FLIGHT_ID_2,
                assembly(rid(), 0, List.of(uld("AKE00001", "AKE", "FWD", 100, 900))));
        assertThat(d2.version()).isEqualTo(1);
    }

    @Test
    void lmcReprintRequiresNewDiagramMatchingLatestManifest() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, standardDiagram()));

        // 超限 LMC 重打：装配图仍绑定旧舱单（可追溯），新舱单需重新提交装配图
        ManifestResponse v2 = service.applyLmc(FLIGHT_ID, new LmcRequest(rid(), 6, "PAX_F",
                new BigDecimal("80"), BigDecimal.ZERO, "CARGO", "CARGO_F", BigDecimal.ZERO, "lc001"));
        assertThat(v2.versionNo()).isEqualTo(2);
        assertThat(service.getCurrentAssembly(FLIGHT_ID).manifestId()).isNotEqualTo(v2.manifestId());

        // 复核通过后关闭仍被拒：图与舱单版本不匹配
        reviewBoth(FLIGHT_ID);
        assertThatThrownBy(() -> service.close(FLIGHT_ID, new CloseRequest(rid(), "captain")))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("不匹配");

        // 按新舱单重新提交（占用随图转移），再复核后放行
        AssemblyDiagramResponse d2 = service.submitAssembly(FLIGHT_ID,
                assembly(rid(), 1, standardDiagram()));
        assertThat(d2.manifestId()).isEqualTo(v2.manifestId());
        assertThat(d2.version()).isEqualTo(2);
        reviewBoth(FLIGHT_ID);
        ManifestResponse closed = service.close(FLIGHT_ID, new CloseRequest(rid(), "captain"));
        assertThat(closed.status()).isEqualTo("CLOSED");
    }

    @Test
    void lmcOnControlledManifestRecalculatesWithDiagramAndInvalidatesReviews() {
        ManifestResponse loaded = toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        service.submitAssembly(FLIGHT_ID, assembly(rid(), 0, standardDiagram()));
        service.review(FLIGHT_ID, new ReviewRequest(rid(), "LOAD_CONTROLLER", "lc001"));

        // 货运重量 LMC 被拒：货运业载由装配图管理
        assertThatThrownBy(() -> service.applyLmc(FLIGHT_ID, new LmcRequest(rid(), 0, "PAX_F",
                new BigDecimal("80"), new BigDecimal("100"), "CARGO", "CARGO_F",
                BigDecimal.ZERO, "lc001")))
                .isInstanceOf(UnprocessableException.class)
                .hasMessageContaining("装配图");

        // 加油变更：按装配图力矩重算重心，既有复核失效（复核须对应最新舱单）
        BigDecimal cgTowBefore = service.getActive(FLIGHT_ID).cgTowPct();
        ManifestResponse refueled = service.applyLmc(FLIGHT_ID, new LmcRequest(rid(), 0, "PAX_F",
                new BigDecimal("80"), BigDecimal.ZERO, "CARGO", "CARGO_F",
                new BigDecimal("500"), "lc001"));
        assertThat(refueled.manifestId()).isEqualTo(loaded.manifestId());
        assertThat(refueled.fuelKg()).isEqualByComparingTo("5500.00");
        assertThat(refueled.cgTowPct()).isNotEqualByComparingTo(cgTowBefore);
        assertThat(refueled.confirmedRoles()).isEmpty();
        Integer reviews = jdbc.queryForObject(
                "SELECT COUNT(*) FROM review_confirmation WHERE manifest_id = ?",
                Integer.class, loaded.manifestId());
        assertThat(reviews).isZero();
        // 装配图未变化，仍绑定该舱单可追溯
        assertThat(service.getCurrentAssembly(FLIGHT_ID).manifestId()).isEqualTo(loaded.manifestId());
    }

    // ----------------------------------------------------- 幂等

    @Test
    void sameRequestIdSameParamsReplaysAndDifferentParamsConflicts() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        String key = rid();
        SubmitAssemblyRequest req = assembly(key, 0, standardDiagram());
        AssemblyDiagramResponse first = service.submitAssembly(FLIGHT_ID, req);
        AssemblyDiagramResponse replay = service.submitAssembly(FLIGHT_ID, req);
        assertThat(replay.diagramId()).isEqualTo(first.diagramId());
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).hasSize(1);

        // 同键异参 → 409，不产生新版本
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(key, 0, List.of(
                        uld("AKE00001", "AKE", "FWD", 100, 3900),
                        uld("PMC00002", "PMC", "AFT", 80, 1921)))))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("不同业务参数");
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).hasSize(1);
    }

    @Test
    void failedSubmitDoesNotOccupyIdempotencyKey() {
        toLoaded(FLIGHT_ID, baseItems(), new BigDecimal("5000"));
        String key = rid();
        // 首次失败（总货重不符 422）：事务回滚不占键
        assertThatThrownBy(() -> service.submitAssembly(FLIGHT_ID,
                assembly(key, 0, List.of(uld("AKE00001", "AKE", "FWD", 100, 3900)))))
                .isInstanceOf(UnprocessableException.class);
        Integer keys = jdbc.queryForObject(
                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = ?", Integer.class, key);
        assertThat(keys).isZero();

        // 同键修正参数后成功
        AssemblyDiagramResponse ok = service.submitAssembly(FLIGHT_ID,
                assembly(key, 0, standardDiagram()));
        assertThat(ok.version()).isEqualTo(1);
    }
}

