import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * H2 并发测试：并发改图仅一方推进版本；两航班抢同一集装器仅一笔占用成功；
 * 同键并发提交回放同一冻结结果。
 */
class AssemblyDiagramConcurrencyTest extends AbstractIntegrationTest {

    private static final long FLIGHT_ID = 1L;
    private static final long FLIGHT_ID_2 = 2L;

    @Autowired
    private WeightBalanceService service;

    private static String rid() {
        return UUID.randomUUID().toString();
    }

    private static List<LoadItem> items(int cargoPieces) {
        return List.of(
                new LoadItem("PASSENGER", "PAX_F", 90, new BigDecimal("80")),
                new LoadItem("CARGO", "CARGO_F", cargoPieces, new BigDecimal("1000")));
    }

    private void toLoaded(long flightId, int cargoPieces) {
        List<LoadItem> items = items(cargoPieces);
        service.createManifest(new CreateManifestRequest(rid(), flightId, new BigDecimal("5000"), "lc001", items));
        service.checkin(flightId, new CheckinRequest(rid(), items, new BigDecimal("5000"), "a"));
        service.confirmLoad(flightId, new StageRequest(rid(), "loader"));
    }

    private static SubmitAssemblyRequest diagram(String requestId, long expectedVersion, String uldNumber,
                                                 int fwdNet, int aftNet) {
        return new SubmitAssemblyRequest(requestId, expectedVersion, List.of(
                new AssemblyItemRequest(uldNumber, "AKE", "FWD", 100, fwdNet),
                new AssemblyItemRequest("PMC" + uldNumber.substring(3), "PMC", "AFT", 80, aftNet)),
                "lc001", LocalDateTime.of(2026, 9, 27, 9, 30, 0));
    }

    @Test
    void concurrentDiagramEditsOnlyOneAdvancesVersion() throws Exception {
        toLoaded(FLIGHT_ID, 6);
        int threads = 6;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger success = new AtomicInteger();
        AtomicInteger rejected = new AtomicInteger();
        List<Future<?>> futures = new java.util.ArrayList<>();
        for (int i = 0; i < threads; i++) {
            final int n = i;
            futures.add(pool.submit(() -> {
                start.await();
                try {
                    // 全部以 expectedVersion=0 抢首版：仅一方成功，其余版本冲突或并发拒绝
                    service.submitAssembly(FLIGHT_ID,
                            diagram(rid(), 0, "AKE0000" + n, 3900, 1920));
                    success.incrementAndGet();
                } catch (ConflictException | UnprocessableException e) {
                    rejected.incrementAndGet();
                }
                return null;
            }));
        }
        start.countDown();
        for (Future<?> f : futures) {
            f.get(30, TimeUnit.SECONDS);
        }
        pool.shutdown();
        assertThat(success.get()).isEqualTo(1);
        assertThat(rejected.get()).isEqualTo(threads - 1);
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).hasSize(1);
        assertThat(service.getCurrentAssembly(FLIGHT_ID).version()).isEqualTo(1);
    }

    @Test
    void twoFlightsGrabbingSameUldOnlyOneSucceeds() throws Exception {
        toLoaded(FLIGHT_ID, 6);
        // 航班 2 货运业载 1000kg：单器 FWD 恰 1000
        List<LoadItem> items2 = List.of(
                new LoadItem("PASSENGER", "PAX_F", 10, new BigDecimal("80")),
                new LoadItem("CARGO", "CARGO_F", 1, new BigDecimal("1000")));
        service.createManifest(new CreateManifestRequest(rid(), FLIGHT_ID_2, new BigDecimal("3000"), "lc001", items2));
        service.checkin(FLIGHT_ID_2, new CheckinRequest(rid(), items2, new BigDecimal("3000"), "a"));
        service.confirmLoad(FLIGHT_ID_2, new StageRequest(rid(), "loader"));

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger success = new AtomicInteger();
        AtomicInteger rejected = new AtomicInteger();
        Runnable flight1 = () -> {
            awaitQuiet(start);
            try {
                service.submitAssembly(FLIGHT_ID, diagram(rid(), 0, "AKE00001", 3900, 1920));
                success.incrementAndGet();
            } catch (UnprocessableException | ConflictException e) {
                rejected.incrementAndGet();
            }
        };
        Runnable flight2 = () -> {
            awaitQuiet(start);
            try {
                // 同编号 AKE00001 抢装航班 2（单器即满货运业载 1000kg）
                service.submitAssembly(FLIGHT_ID_2, new SubmitAssemblyRequest(rid(), 0L, List.of(
                        new AssemblyItemRequest("AKE00001", "AKE", "FWD", 100, 900)),
                        "lc001", LocalDateTime.of(2026, 9, 27, 9, 30, 0)));
                success.incrementAndGet();
            } catch (UnprocessableException | ConflictException e) {
                rejected.incrementAndGet();
            }
        };
        Future<?> f1 = pool.submit(flight1);
        Future<?> f2 = pool.submit(flight2);
        start.countDown();
        f1.get(30, TimeUnit.SECONDS);
        f2.get(30, TimeUnit.SECONDS);
        pool.shutdown();

        assertThat(success.get()).isEqualTo(1);
        assertThat(rejected.get()).isEqualTo(1);
        // 同编号全局仅一笔有效占用
        Integer occupied = jdbc.queryForObject(
                "SELECT COUNT(*) FROM uld_occupancy WHERE uld_number='AKE00001' AND active_marker=1",
                Integer.class);
        assertThat(occupied).isEqualTo(1);
    }

    @Test
    void concurrentSameRequestIdSameParamsReplaySingleDiagram() throws Exception {
        toLoaded(FLIGHT_ID, 6);
        String key = rid();
        int threads = 4;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<AssemblyDiagramResponse>> futures = new java.util.ArrayList<>();
        for (int i = 0; i < threads; i++) {
            futures.add(pool.submit(() -> {
                start.await();
                return service.submitAssembly(FLIGHT_ID, diagram(key, 0, "AKE00001", 3900, 1920));
            }));
        }
        start.countDown();
        Long firstId = null;
        for (Future<AssemblyDiagramResponse> f : futures) {
            AssemblyDiagramResponse r = f.get(30, TimeUnit.SECONDS);
            if (firstId == null) {
                firstId = r.diagramId();
            }
            assertThat(r.diagramId()).isEqualTo(firstId);
            assertThat(r.version()).isEqualTo(1);
        }
        pool.shutdown();
        assertThat(service.listAssemblyVersions(FLIGHT_ID)).hasSize(1);
        Integer diagrams = jdbc.queryForObject(
                "SELECT COUNT(*) FROM assembly_diagram WHERE flight_id=1", Integer.class);
        assertThat(diagrams).isEqualTo(1);
    }

    private static void awaitQuiet(CountDownLatch latch) {
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

