package com.example.starter.wb.web;

import com.example.starter.wb.AbstractIntegrationTest;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 集装器装配图 HTTP 契约：提交→查询→复核→关闭全链路，含 400/404/409/422 语义。
 */
class AssemblyDiagramApiTest extends AbstractIntegrationTest {

    @Autowired
    private WebApplicationContext wac;

    private MockMvc mvc;

    private MockMvc rest() {
        if (mvc == null) {
            mvc = MockMvcBuilders.webAppContextSetup(wac).build();
        }
        return mvc;
    }

    private static String rid() {
        return UUID.randomUUID().toString();
    }

    private void toLoaded() throws Exception {
        String items = """
                [
                  {"category":"PASSENGER","stationCode":"PAX_F","pieces":90,"unitWeightKg":80},
                  {"category":"CARGO","stationCode":"CARGO_F","pieces":6,"unitWeightKg":1000}
                ]
                """;
        rest().perform(post("/api/flights/1/loadsheet")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","flightId":1,"fuelKg":5000,"createdBy":"lc001","items":%s}
                                """.formatted(rid(), items)))
                .andExpect(status().isCreated());
        rest().perform(post("/api/flights/1/loadsheet/checkin")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","fuelKg":5000,"operator":"a","items":%s}
                                """.formatted(rid(), items)))
                .andExpect(status().isOk());
        rest().perform(post("/api/flights/1/loadsheet/confirm-load")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","operator":"loader"}""".formatted(rid())))
                .andExpect(status().isOk());
    }

    private static String assemblyBody(String requestId, long expectedVersion) {
        return """
                {
                  "requestId": "%s",
                  "expectedVersion": %d,
                  "operator": "lc001",
                  "occurredAt": "2026-09-27T09:30:00",
                  "items": [
                    {"uldNumber":"AKE00001","uldType":"AKE","compartmentCode":"FWD","tareKg":100,"netKg":3900},
                    {"uldNumber":"PMC00002","uldType":"PMC","compartmentCode":"AFT","tareKg":80,"netKg":1920}
                  ]
                }
                """.formatted(requestId, expectedVersion);
    }

    @Test
    void assemblyHttpFlowSubmitQueryReviewClose() throws Exception {
        toLoaded();
        String key = rid();
        // 提交装配图：版本 1，总货重 6000kg = 货运业载，力矩精确求和
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(assemblyBody(key, 0)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1))
                .andExpect(jsonPath("$.status").value("CURRENT"))
                .andExpect(jsonPath("$.totalWeightKg").value(6000))
                .andExpect(jsonPath("$.totalMomentKgmm").value(91440000L))
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].totalKg").value(4000));

        // 同键同参回放首次冻结结果
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(assemblyBody(key, 0)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1));

        // 当前图与版本链查询
        rest().perform(get("/api/flights/1/loadsheet/assembly"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1));
        rest().perform(get("/api/flights/1/loadsheet/assembly/versions"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1));

        // 双岗复核后关闭：占用原子释放
        rest().perform(post("/api/flights/1/loadsheet/review")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","role":"LOAD_CONTROLLER","reviewer":"lc001"}"""
                                .formatted(rid())))
                .andExpect(status().isOk());
        rest().perform(post("/api/flights/1/loadsheet/review")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","role":"FLIGHT_DISPATCHER","reviewer":"fd002"}"""
                                .formatted(rid())))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REVIEWED"));
        rest().perform(post("/api/flights/1/loadsheet/close")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"%s","closedBy":"captain"}""".formatted(rid())))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CLOSED"));

        // 历史图只读：关闭后提交被拒
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(assemblyBody(rid(), 1)))
                .andExpect(status().isConflict());
    }

    @Test
    void assemblyValidationAndVersionErrorsMapToHttpSemantics() throws Exception {
        toLoaded();
        // 缺字段 → 400
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content("{}"))
                .andExpect(status().isBadRequest());
        // 无图航班查询 → 404
        rest().perform(get("/api/flights/2/loadsheet/assembly"))
                .andExpect(status().isNotFound());
        // 期望版本不符 → 409
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(assemblyBody(rid(), 5)))
                .andExpect(status().isConflict());
        // 总货重与货运业载不符 → 422
        String badTotal = assemblyBody(rid(), 0).replace("\"netKg\":1920", "\"netKg\":1820");
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(badTotal))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.message").value(
                        org.hamcrest.Matchers.containsString("货运业载")));
        // 舱位超限 → 422
        String overLimit = assemblyBody(rid(), 0).replace("\"netKg\":3900", "\"netKg\":3901")
                .replace("\"netKg\":1920", "\"netKg\":1919");
        rest().perform(post("/api/flights/1/loadsheet/assembly")
                        .contentType(MediaType.APPLICATION_JSON).content(overLimit))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.message").value(
                        org.hamcrest.Matchers.containsString("限额")));
    }
}

